INSERT INTO `templates` VALUES (1,'signup','Welcome to Oilcop Support','{name} , <br>\r\nThank you for signing up for OilCop Support, the link below will redirect you to the web portal. You may change your user name and password after logging in. If you have any questions or need assistance please email helpdesk@oilcopsupport.com.\r\n<br><br>\r\nhttp://www.oilcopsupport.com/ <br> <br>\r\nUser Name : {username} <br>\r\nPassword : {password}\r\n<br><br>\r\nThank you,<br>\r\nOilCop Team.',0,'1346386716','1434966710'),(2,'Open Discrepancy','New Discrepancy Opened','Dear Member, <br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; A new discrepancy has been posted.\n <br>\n<b>Discrepancy Id</b>: {discp_id}  <br>\n<b>Discrepancy Title</b>: {discp_title}  <br>\n<b>Discrepancy info</b>: {discp_info}  <br> \n<b>Assigned to</b>: {ass_to}  <br>\n<b>Opened by</b>: {opened_user} <br>\n<b>Date</b>:{pdate} \n <br><br>\n{link} \n <br><br>\nThanks',0,'',''),(3,'Software version update','Software version update','Dear Member,\r\n\r\n    Version {name} is available to update the systems.\r\n<br>\r\n Version details : {info} \r\n<br>\r\nThanks',0,'',''),(4,'Close Discrepancy','Discrepancy was closed.','Dear Member, <br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Discrepancy has been closed.\n <br>\n<b>Discrepancy Id</b>: {discp_id}  <br>\n<b>Discrepancy title</b>: {discp_title}  <br> \n<b>Discrepancy info</b>: {discp_info}  <br> \n<b>Comments </b>: <br>\n  {comments} \n<b>Closed by</b>: {closed_by} <br>\n<b>Date</b>:{pdate} \n <br><br>\n{link} \n <br><br>\nThanks',0,'',''),(5,'Forgot Password','Forgot Password','Dear Member,<br>\r\n   Forgot your password? It\'s okay. <br/>Please click on the following link to reset your password<br/><br>\r\n {reset_link}  <br/><br>\r\n   If you did not request to change your password, please ignore this email and no changes will be made to your account.',0,'',''),(6,'Discrepancy_commented','Discrepancy updated','Dear Member, <br>\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Discrepancy has been updated.<br>\n<b>Discrepancy Id</b>: {discp_id}  <br>\n<b>Discrepancy Title</b>: {discp_title}  <br>\n<b>Discrepancy info</b>: {discp_info}  <br> \n<b>Assigned to</b>: {ass_to}  <br>\n<b>Comment </b>: {comment} <br>\n<b>Commented by </b>: {commented_by} <br>\n<b>Commented On</b>:{cdate} \n <br><br>\n{link} \n <br><br>\nThanks',0,'','');
/*!40000 ALTER TABLE `templates` ENABLE KEYS */;
UNLOCK TABLES;

